import React, { useState } from 'react';
import { CLoading, CRadio, Divider, Message } from '@cloud-materials/common';

const statusOptions = [
  {
    value: 'loading',
    label: '加载中',
  },
  {
    value: 'error',
    label: '加载出错',
  },
  {
    value: 'success',
    label: '加载成功',
  },
];
export default () => {
  const [status, setStatus] = useState('loading');
  return (
    <div>
      <CRadio.Group options={statusOptions} value={status} onChange={setStatus} />
      <Divider />
      <span>默认加载：</span>
      <CLoading loading={status === 'loading'} hasError={status === 'error'} onReload={() => Message.info('重新加载')}>
        <input />
      </CLoading>
    </div>
  );
};

